parameters.jsCode:
const signals = JSON.parse(items[0].json.stdout || '[]');
return signals.map(s => ({
  json: {
    ...s,
    color: s.signal_type.includes('BUY') ? 3066993 : 15158332,
    emoji: s.signal_type.includes('BUY') ? '🟢' : '🔴',
    analysts: JSON.parse(s.recent_analyst_calls_json || '[]')
  }
}));

